layer.css:
[data-ryt="footer"] { color: var(--ryt-muted); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-weight: 700; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-size: 30px; font-weight: 800; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: rgb(122, 90, 28); background-color: rgba(255, 255, 255, 0.66); border-top: 1px solid rgb(210, 210, 210); border-right: 1px solid rgb(210, 210, 210); border-bottom: 1px solid rgb(210, 210, 210); border-left: 1px solid rgb(210, 210, 210); border-radius: 999px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-size: 14.5px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(122, 90, 28); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 14px; padding-bottom: 0px; padding-left: 14px; transition: all }
[data-ryt="button"] { color: rgb(122, 90, 28); background-color: rgba(255, 255, 255, 0.66); border-top: 1px solid rgb(210, 210, 210); border-right: 1px solid rgb(210, 210, 210); border-bottom: 1px solid rgb(210, 210, 210); border-left: 1px solid rgb(210, 210, 210); border-radius: 999px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(122, 90, 28); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 14px; padding-bottom: 0px; padding-left: 14px; transition: all }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-muted); border-radius: 0px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="review"] { color: var(--ryt-muted); font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-size: 14.2px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-size: 13.5px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="cover"] { border-top: 1px solid rgb(220, 220, 220); border-right: 1px solid rgb(220, 220, 220); border-bottom: 1px solid rgb(220, 220, 220); border-left: 1px solid rgb(220, 220, 220); border-radius: 18px; filter: brightness(1) }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(58, 69, 92); border-radius: 0px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-weight: 500; font-style: normal; letter-spacing: -0.15px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(58, 69, 92); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif, "PingFang SC", "Microsoft YaHei", "Noto Sans CJK SC", "Source Han Sans SC"; font-size: 15px; font-weight: 500; font-style: normal; line-height: 1.35; letter-spacing: -0.15px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
